/* Armoiries officielles de la République Centrafricaine (SVG fourni, embarqué en base64) */
const ARMOIRIES_SRC = "data:image/svg+xml;base64,";

function Filigrane({ opacity = 0.05, size = "min(72vh, 72vw)" }) {
  return (
    <div aria-hidden="true" style={{ position: "fixed", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", pointerEvents: "none", zIndex: 0 }}>
      <img src={ARMOIRIES_SRC} alt="" style={{ width: size, opacity, filter: "grayscale(35%)" }} />
    </div>
  );
}

/* Bandeau aux couleurs du drapeau national — les couleurs sur une seule ligne */
function FlagBandRCA({ width = "100%", height = 12 }) {
  return (
    <svg width={width} height={height} viewBox="0 0 300 24" preserveAspectRatio="none" role="img" aria-label="Couleurs du drapeau de la République Centrafricaine" style={{ display: "block", borderRadius: 2, boxShadow: "0 1px 3px rgba(0,0,0,.35)" }}>
      <rect x="0" y="0" width="60" height="24" fill="#003082" />
      <rect x="60" y="0" width="60" height="24" fill="#FFFFFF" />
      <rect x="120" y="0" width="60" height="24" fill="#D21034" />
      <rect x="180" y="0" width="60" height="24" fill="#289728" />
      <rect x="240" y="0" width="60" height="24" fill="#FFCE00" />
      <path d="M30 4 l2.6 5.4 6 .6 -4.4 4 1.3 5.8 -5.5 -3.1 -5.5 3.1 1.3 -5.8 -4.4 -4 6 -.6 Z" fill="#FFCE00" />
    </svg>
  );
}

function ArmoiriesRCA({ size = 64 }) {
  return (
    <img src={ARMOIRIES_SRC} alt="Armoiries de la République Centrafricaine"
      style={{ width: size, height: "auto", display: "block", filter: "drop-shadow(0 1px 2px rgba(0,0,0,0.35))" }} />
  );
}

