const LangCtx = createContext({ lang: "fr", setLang: () => {} });
const useT = () => {
  const { lang } = useContext(LangCtx);
  return (k) => (TR[k] ? TR[k][lang] || TR[k].fr : k);
};

function LangSwitch({ dark }) {
  const { lang, setLang } = useContext(LangCtx);
  return (
    <div style={{ display: "flex", gap: 4 }}>
      {["fr", "en", "ru"].map((l) => (
        <button key={l} onClick={() => setLang(l)}
          style={{ cursor: "pointer", border: `1px solid ${dark ? C.gold : C.line}`, borderRadius: 3, padding: "3px 8px", fontSize: 11, fontWeight: 800, letterSpacing: 1,
            background: lang === l ? C.gold : "transparent", color: lang === l ? C.navyDeep : dark ? C.goldSoft : C.navy }}>
          {l.toUpperCase()}
        </button>
      ))}
    </div>
  );
}

