/* ---------------- Utilitaires ---------------- */

const fmtDT = (iso) => {
  if (!iso) return "—";
  const d = new Date(iso);
  return d.toLocaleDateString("fr-FR", { day: "2-digit", month: "2-digit", year: "numeric" }) + " " + d.toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" });
};
const fmtD = (s) => (s ? new Date(s + "T00:00:00").toLocaleDateString("fr-FR") : "—");
const uid = (p) => p + Math.random().toString(36).slice(2, 8).toUpperCase();
const numFiche = () => `CNH-${new Date().getFullYear()}-${Math.floor(100000 + Math.random() * 900000)}`;
const codeVerif = (r) => {
  let h = 5381;
  const str = (r.id || "") + (r.nom || "") + (r.numDoc || "") + (r.entree || "");
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  return h.toString(16).toUpperCase().padStart(8, "0");
};
const norm = (s) => (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]/g, "");

