function countryName(a2, lang) {
  try {
    const dn = new Intl.DisplayNames([lang], { type: "region" });
    return dn.of(a2) || a2;
  } catch (e) { return a2; }
}

/* Options triées dans la langue courante, RCA toujours en tête */
function useCountryOptions() {
  const { lang } = useContext(LangCtx);
  return useMemo(() => {
    const list = COUNTRIES.map(([a2, a3, dial]) => ({ a2, a3, dial, name: countryName(a2, lang) }));
    list.sort((a, b) => (a.a3 === "CAF" ? -1 : b.a3 === "CAF" ? 1 : a.name.localeCompare(b.name, lang)));
    return list;
  }, [lang]);
}


function parseMRZ(raw) {
  const lines = raw.toUpperCase().replace(/ /g, "").split(/\n+/).map((l) => l.trim()).filter(Boolean);
  const yy = (s) => { const n = parseInt(s, 10); return n > 30 ? "19" + s : "20" + s; };
  const dob = (s) => (/^\d{6}$/.test(s) ? `${yy(s.slice(0, 2))}-${s.slice(2, 4)}-${s.slice(4, 6)}` : "");
  try {
    if (lines.length >= 2 && lines[0].startsWith("P")) {
      const l1 = lines[0].padEnd(44, "<"), l2 = lines[1].padEnd(44, "<");
      const names = l1.slice(5).split("<<");
      return { typeDoc: "PASSEPORT", nom: (names[0] || "").replace(/</g, " ").trim(), prenom: (names[1] || "").replace(/</g, " ").trim(),
        numDoc: l2.slice(0, 9).replace(/</g, ""), nationalite: l2.slice(10, 13).replace(/</g, ""), dateNaissance: dob(l2.slice(13, 19)),
        sexe: l2[20] === "F" ? "F" : l2[20] === "M" ? "M" : "" };
    }
    if (lines.length >= 3 && (lines[0].startsWith("I") || lines[0].startsWith("A") || lines[0].startsWith("C"))) {
      const l1 = lines[0].padEnd(30, "<"), l2 = lines[1].padEnd(30, "<"), l3 = lines[2].padEnd(30, "<");
      const names = l3.split("<<");
      return { typeDoc: "CNI", numDoc: l1.slice(5, 14).replace(/</g, ""), dateNaissance: dob(l2.slice(0, 6)),
        sexe: l2[7] === "F" ? "F" : l2[7] === "M" ? "M" : "", nationalite: l2.slice(15, 18).replace(/</g, ""),
        nom: (names[0] || "").replace(/</g, " ").trim(), prenom: (names[1] || "").replace(/</g, " ").trim() };
    }
  } catch (e) { /* ignore */ }
  return null;
}

/* ---------------- Export : fiche imprimable & CSV ---------------- */

function downloadFile(name, content, mime) {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = name;
  document.body.appendChild(a); a.click();
  setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 300);
}

const csvEsc = (v) => '"' + String(v == null ? "" : v).replace(/"/g, '""') + '"';

function exportCSV(rows, hotels, filename) {
  const head = ["N° fiche", "Réf.", "Hôtel", "Préfecture", "Ville", "Nom", "Prénom", "Sexe", "Date de naissance", "Nationalité", "Type de pièce", "N° document", "Téléphone", "E-mail", "Chambre", "Motif", "Provenance", "Destination", "Entrée", "Sortie", "Signalé"];
  const lines = rows.map((r) => {
    const h = hotels.find((x) => x.id === r.hotelId) || {};
    return [r.fiche || "", r.id, h.nom || "", h.prefecture || "", h.ville || "", r.nom, r.prenom, r.sexe, r.dateNaissance, r.nationalite, r.typeDoc, r.numDoc, r.telephone, r.email, r.chambre, r.motif, r.provenance, r.destination, fmtDT(r.entree), fmtDT(r.sortie), r.signale ? "OUI" : "NON"].map(csvEsc).join(";");
  });
  downloadFile(filename, "\uFEFF" + head.map(csvEsc).join(";") + "\n" + lines.join("\n"), "text/csv;charset=utf-8");
}

